"""Development-only literal data exporter; does not translate PHP algorithms."""
import json
import re
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent

def write(name, data):
    (ROOT / 'js/data' / (name + '.js')).write_text(
        '// Original Wizardawn literal tables. Generated by extract-tables.py.\n'
        'window.WZ_DATA = window.WZ_DATA || {};\nwindow.WZ_DATA.' + name + ' = ' + json.dumps(data, ensure_ascii=False) + ';\n')

def arrays(text):
    for m in re.finditer(r'\$(\w+)\s*=\s*array\(', text):
        start = m.end()
        i, depth, quote = start, 1, None
        while i < len(text) and depth:
            c = text[i]
            if c == '\\' and quote:
                i += 2
                continue
            if quote:
                if c == quote:
                    quote = None
            elif c in "'\"":
                quote = c
            elif c == '(':
                depth += 1
            elif c == ')':
                depth -= 1
            i += 1
        raw = text[start:i-1]
        tokens = re.findall(r"'(?:[^'\\]|\\.)*'|\"(?:[^\"\\]|\\.)*\"|[-+]?\d+(?:\.\d+)?", raw)
        rest = re.sub(r"'(?:[^'\\]|\\.)*'|\"(?:[^\"\\]|\\.)*\"|[-+]?\d+(?:\.\d+)?", '', raw)
        if rest.replace(',', '').strip() or not tokens:
            continue
        values = []
        for token in tokens:
            if token[0] in "'\"":
                v = token[1:-1].replace('\\' + token[0], token[0]).replace('\\\\', '\\')
                if token[0] == '"':
                    v = v.replace('\\n', '\n').replace('\\t', '\t').replace('\\r', '\r')
                    if '$' in v:
                        raise ValueError('Interpolated PHP is not literal data: ' + m[1])
                values.append(v)
            else:
                values.append(float(token) if '.' in token else int(token))
        yield m[1], values

def function_tables(file, names):
    text = (ROOT / 'src/functions' / (file + '.php')).read_text(encoding='cp1252')
    result = {}
    for part in re.split(r'(?m)^function\s+', text)[1:]:
        name = re.match(r'\w+', part)[0]
        if name in names:
            result[name] = {}
            for key, values in arrays(part):
                result[name].setdefault(key, []).append(values)
    return result

