    image, rooms, spot, more, delve, terrain, wayout = parts
    geo_rows.append(dict(image=image, rooms=[int(r) for r in rooms.split('_') if r.isdigit() and int(r)], spot=spot, more=more, delve=delve, terrain=terrain, wayout=int(wayout or 0)))
